// Block (composition) — Panel: a deal-led sibling of ProductCard, with one destination and no nested action.
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Card, CardMedia } from "../components/Card";
import { Link } from "../components/Link";
import { Text } from "../components/Text";
import { AspectRatio } from "../layouts/AspectRatio";
import { Stack } from "../layouts/Stack";
import "./DealCard.css";

export interface DealCardProps {
  title: string;
  href: string;
  discount: string;
  image: { src: string; alt: string };
  price: string;
  originalPrice: string;
  originalPriceLabel?: string;
  /**
   * The picture band, which must contrast with the ground the CARD sits on: `well` (default) a grey
   * plate for a card on a white page, `plain` no plate for a card on a grey `Band`, where the
   * cut-out sits contained on the card's own white surface.
   *
   * @default "well"
   */
  mediaVariant?: "well" | "plain";
  className?: string;
  ref?: Ref<HTMLAnchorElement>;
}

export function DealCard({ title, href, discount, image, price, originalPrice,
  originalPriceLabel = "List price", mediaVariant = "well", className, ref }: DealCardProps) {
  return (
    // No aria-label: the Link is named by its content, so the name holds every word the card shows
    // (WCAG 2.5.3 Label in Name), the picture's alt first and then the title, discount and prices.
    <Link href={href} ref={ref} variant="quiet"
      className={className ? `sd-dealcard ${className}` : "sd-dealcard"}>
      <Card className="sd-dealcard__surface">
        {/* The picture is the card's top, a band edge to edge: CardMedia plates the cut-out device
            render on the well and contains it whole. */}
        <CardMedia variant={mediaVariant}>
          <AspectRatio ratio={4 / 3}>
            <img src={image.src} alt={image.alt} />
          </AspectRatio>
        </CardMedia>
        {/* The row wraps, as ProductCard's heading does: when the name and the discount do not fit side by
            side the discount drops under the name, so a narrow column never squeezes the name mid-word. */}
        <Stack direction="row" align="center" justify="between" gap="small" wrap>
          {/* Two lines before the cut, so a long model name still reads; the Link's name is the whole text. */}
          <Text elementType="h3" variant="title" size="medium" maxLines={2} className="sd-dealcard__title">
            {title}
          </Text>
          {/* Badge law: a discount is a reason to act now with no status attached, `urgency`. */}
          <Badge variant="urgency" className="sd-dealcard__discount">{discount}</Badge>
        </Stack>
        <Stack gap="x-small" className="sd-dealcard__detail">
          {/* CONTRASTIVE: one rung above the model name it prices, as the card exists to show it. */}
          <p className="sd-dealcard__price sd-type-title-large-emphasized">{price}</p>
          <p className="sd-dealcard__original sd-type-caption-medium">
            {originalPriceLabel} <s>{originalPrice}</s>
          </p>
        </Stack>
      </Card>
    </Link>
  );
}

/* Arrangement only; Link owns interaction and Card owns the surface. */
.sd-dealcard {
  display: flex;
  min-width: 0;
  width: 100%;
}
.sd-dealcard__surface {
  flex: 1;
  min-width: 0;
}
.sd-dealcard__title,
.sd-dealcard__price,
.sd-dealcard__original {
  margin: 0;
}
.sd-dealcard__title {
  min-width: 0;
}
.sd-dealcard__discount {
  flex-shrink: 0;
}
.sd-dealcard__detail {
  margin-block-start: auto;
}
.sd-dealcard__original {
  color: var(--sd-color-text-muted);
}
